package crawler; import java.util.List; public class CrawlerDemo { public static void main(String[] args) { WebCrawler crawler = new WebCrawler(); List<WebCrawler.PaginaResultado> resultados = crawler.crawlMultiple("https://www.gub.uy", 5); System.out.println("\n--- Resumen final ---"); System.out.println("Páginas analizadas: " + resultados.size()); for (WebCrawler.PaginaResultado r : resultados) { System.out.println(r.url + " → inputs: " + r.info.inputNames.size() + ", botones: " + r.info.buttonTexts.size()); } } }